                <p className="text-on-surface-variant text-sm mt-1">
                  {formatHours(project.total_seconds)} hrs
                  {project.languages?.length ? ` · ${project.languages.join(', ')}` : ''}
                </p>
              </button>
            )
          })}
        </div>
      )}
    </div>
  )
}

