import { createHash } from 'node:crypto'
import { EncryptJWT, jwtDecrypt } from 'jose'

const SESSION_COOKIE = 'session'
const SESSION_TTL_SECONDS = 60 * 60 * 24 * 7 // 7 days

// A256GCM requires exactly a 32-byte key; SESSION_SECRET can be any length,
// so it's hashed down to a fixed-size key rather than used directly.
function getSessionKey() {
  const secret = process.env.SESSION_SECRET
  if (!secret) {
    throw new Error('SESSION_SECRET is not set')
  }
  return createHash('sha256').update(secret).digest()
}

// Session payload is exactly the OAuth tokens — nothing else is ever stored
// server-side, so there is no session record/table/KV to keep in sync.
// Payload is a plain object so it can carry tokens from both the Hack Club
// identity OAuth hop (access_token, refresh_token, expires_at) and the
// separate Hackatime OAuth hop (hackatime_access_token) — two independent
// OAuth providers, merged into one cookie so the dashboard only needs one
// session read.
export async function encryptSession(payload) {
  const key = getSessionKey()
  return new EncryptJWT({ ...payload })
    .setProtectedHeader({ alg: 'dir', enc: 'A256GCM' })
    .setIssuedAt()
    .setExpirationTime(`${SESSION_TTL_SECONDS}s`)
    .encrypt(key)
}

export async function decryptSession(token) {
  if (!token) return null
  try {
    const key = getSessionKey()
    const { payload } = await jwtDecrypt(token, key)
    return payload
  } catch {
    return null
  }
}

export const sessionCookieOptions = {
  name: SESSION_COOKIE,
  httpOnly: true,
  secure: true,
  sameSite: 'lax',
  path: '/',
  maxAge: SESSION_TTL_SECONDS,
}

export { SESSION_COOKIE }

const LOCAL_HOST = /^(localhost|127\.0\.0\.1|\[::1\])(:\d+)?$/

// Derives the public-facing origin from request headers rather than the
// server's own bind address, which is wrong behind a proxy/in dev containers.
// This is what makes OAuth redirect URIs (Hack Club + Hackatime) work
// automatically on both localhost and the deployed domain — the redirect_uri
// sent to each provider is built from whatever host the request actually
// came in on, so there's nothing to hardcode or swap between environments.
export function getRequestOrigin(request) {
  const forwardedProto = request.headers.get('x-forwarded-proto')
  const forwardedHost = request.headers.get('x-forwarded-host')
  const host = forwardedHost || request.headers.get('host')
  const protocol = forwardedProto || (LOCAL_HOST.test(host ?? '') ? 'http' : 'https')
  return `${protocol}://${host}`
}

export function getRedirectUri(request) {
  return `${getRequestOrigin(request)}/api/auth/callback`
}

import { cookies } from 'next/headers'
import { redirect } from 'next/navigation'
import { SESSION_COOKIE, decryptSession } from './session'

export async function getSession() {
  const cookieStore = await cookies()
  const token = cookieStore.get(SESSION_COOKIE)?.value
  const session = await decryptSession(token)
  if (!session) return null
  if (session.expires_at && Date.now() > session.expires_at) return null
  return session
}

// For server components/pages: redirects to whichever OAuth hop is
// incomplete instead of rendering. A session can exist with only the Hack
// Club identity token if the user never finished (or was interrupted
// during) the second, Hackatime hop.
export async function requireSession() {
  const session = await getSession()
  if (!session) redirect('/api/auth/login')
  if (!session.hackatime_access_token) redirect('/api/auth/hackatime/login')
  return session
}

// For route handlers: returns the session or null so the caller can
// respond with 401 instead of a redirect (redirects don't make sense for
// an API/fetch caller).
export async function getSessionFromRequest() {
  return getSession()
}

